package local.morphtv.legacy;
import android.app.*;import android.os.*;import android.net.*;import android.widget.*;import android.media.*;import android.view.*;
public final class PlayerActivity extends Activity {
 private boolean exitBackPending;private VideoView video;private LinearLayout controls,panel;private TextView info;private Button pause;private MediaPlayer engine;private int accent;private final java.util.Map<Integer,View> trackPanels=new java.util.HashMap<Integer,View>();
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private android.graphics.drawable.GradientDrawable surface(){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(android.graphics.Color.argb(102,Math.round(android.graphics.Color.red(accent)*.28f),Math.round(android.graphics.Color.green(accent)*.28f),Math.round(android.graphics.Color.blue(accent)*.28f)));d.setCornerRadius(dp(12));d.setStroke(dp(1),(accent&0xffffff)|0x66000000);return d;}
 private Button button(String name,final Runnable action){final Button b=new Button(this);b.setText(name);b.setTextColor(0xffedf3fa);b.setTextSize(14);b.setAllCaps(false);b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setPadding(dp(8),dp(5),dp(8),dp(5));b.setBackground(surface());b.setOnFocusChangeListener(new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean focused){b.setTextColor(focused?accent:0xffedf3fa);}});b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});return b;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);String url=getIntent().getStringExtra("url");if(!Playlist.valid(url)){finish();return;}
  accent=getIntent().getIntExtra("accent",0xffd2def4);getWindow().getDecorView().setSystemUiVisibility(5894);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff000000);video=new VideoView(this);root.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));
  Button back=button(getResources().getConfiguration().locale.getLanguage().equals("ar")?"‹ رجوع":"‹ Back",new Runnable(){public void run(){finish();}});back.setContentDescription("Back to previous list");FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(dp(132),dp(52),Gravity.TOP|Gravity.LEFT);bp.setMargins(dp(14),dp(14),0,0);root.addView(back,bp);
  controls=new LinearLayout(this);controls.setOrientation(1);controls.setPadding(dp(12),dp(6),dp(12),dp(6));controls.setBackgroundColor(android.graphics.Color.TRANSPARENT);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(getResources().getDisplayMetrics().widthPixels/2,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);cp.bottomMargin=dp(16);root.addView(controls,cp);info=new TextView(this);info.setText(getIntent().getStringExtra("name"));info.setTextColor(0xffedf3fa);info.setTextSize(15);info.setPadding(0,0,0,dp(10));
  LinearLayout row=new LinearLayout(this);controls.addView(row);row.addView(button("−10",new Runnable(){public void run(){seek(-10000);}}),new LinearLayout.LayoutParams(0,dp(48),1));pause=button("Ⅱ",new Runnable(){public void run(){if(video.isPlaying()){video.pause();pause.setText("▶");}else{video.start();pause.setText("Ⅱ");}}});row.addView(pause,new LinearLayout.LayoutParams(0,dp(48),1));row.addView(button("+10",new Runnable(){public void run(){seek(10000);}}),new LinearLayout.LayoutParams(0,dp(48),1));row.addView(button("⚙",new Runnable(){public void run(){panel.setVisibility(panel.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);controls.setVisibility(View.VISIBLE);if(panel.getVisibility()==View.VISIBLE)panel.getChildAt(0).requestFocus();}}),new LinearLayout.LayoutParams(0,dp(48),1));
  panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(8),dp(12),dp(8),dp(12));android.graphics.drawable.GradientDrawable side=surface();side.setCornerRadius(0);panel.setBackground(side);FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.225f),-1,Gravity.RIGHT);pp.setMargins(0,0,0,0);root.addView(panel,pp);panel.setVisibility(View.GONE);android.view.View.OnTouchListener touch=new android.view.View.OnTouchListener(){public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==android.view.MotionEvent.ACTION_UP){boolean shown=controls.getVisibility()==View.VISIBLE;panel.setVisibility(View.GONE);controls.setVisibility(shown?View.GONE:View.VISIBLE);}return true;}};video.setOnTouchListener(touch);root.setOnTouchListener(touch);
  settingsSection("Aspect Ratio",new String[]{"Fit","Fill"},new Runnable[]{new Runnable(){public void run(){aspect(false);}},new Runnable(){public void run(){aspect(true);}}});
  panel.addView(button("Audio Tracks",new Runnable(){public void run(){tracks(MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO);}}));panel.addView(button("Subtitles",new Runnable(){public void run(){tracks(MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_TIMEDTEXT);}}));TextView note=new TextView(this);note.setText("Android 4.4 compatibility player\nQuality and codecs depend on the source. Speed and PiP require a newer Android version.");note.setTextColor(0xffa9bacd);note.setTextSize(12);note.setPadding(dp(8),dp(18),dp(8),0);panel.addView(note);setContentView(root);
  video.setOnPreparedListener(new MediaPlayer.OnPreparedListener(){public void onPrepared(MediaPlayer p){engine=p;video.start();info.setText(String.valueOf(getIntent().getStringExtra("name"))+" · "+p.getVideoHeight()+"p");}});pause.requestFocus();
  video.setOnCompletionListener(new MediaPlayer.OnCompletionListener(){public void onCompletion(MediaPlayer p){finish();}});
  video.setOnErrorListener(new MediaPlayer.OnErrorListener(){public boolean onError(MediaPlayer p,int what,int extra){new AlertDialog.Builder(PlayerActivity.this).setMessage("This stream or codec is not supported by this device (error "+what+"/"+extra+"). No retry was made.").setPositiveButton("OK",new android.content.DialogInterface.OnClickListener(){public void onClick(android.content.DialogInterface d,int w){finish();}}).setOnCancelListener(new android.content.DialogInterface.OnCancelListener(){public void onCancel(android.content.DialogInterface d){finish();}}).show();return true;}});
  video.setVideoURI(Uri.parse(url));video.requestFocus();video.start();
 }
 private void aspect(boolean fill){float scale=1;if(fill&&video.getWidth()>0&&video.getHeight()>0){View parent=(View)video.getParent();scale=Math.max((float)parent.getWidth()/video.getWidth(),(float)parent.getHeight()/video.getHeight());}video.setScaleX(scale);video.setScaleY(scale);} private void seek(int amount){if(video!=null&&video.getDuration()>0)video.seekTo(Math.max(0,Math.min(video.getDuration()-1,video.getCurrentPosition()+amount)));}
 private void settingsSection(String title,String[] names,Runnable[] actions){final LinearLayout options=new LinearLayout(this);options.setOrientation(1);options.setVisibility(View.GONE);Button header=button(title,new Runnable(){public void run(){options.setVisibility(options.getVisibility()==View.GONE?View.VISIBLE:View.GONE);}});panel.addView(header);panel.addView(options);for(int i=0;i<names.length;i++)options.addView(button(names[i],actions[i]));}
 private void tracks(final int type){if(engine==null)return;final LinearLayout options=new LinearLayout(this);options.setOrientation(1);Object previous=trackPanels.get(type);if(previous instanceof View){panel.removeView((View)previous);trackPanels.remove(type);return;}try{MediaPlayer.TrackInfo[] rows=engine.getTrackInfo();for(int i=0;i<rows.length;i++)if(rows[i].getTrackType()==type){final int index=i;options.addView(button(rows[i].getLanguage()+" · "+(i+1),new Runnable(){public void run(){try{engine.selectTrack(index);}catch(Exception ignored){}}}));}if(options.getChildCount()==0){TextView empty=new TextView(this);empty.setText("No tracks exposed by this source");empty.setTextColor(0xffa9bacd);options.addView(empty);}panel.addView(options);trackPanels.put(type,options);}catch(Exception ignored){}}
 @Override public boolean onKeyDown(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_BACK){if(panel.getVisibility()==View.VISIBLE){panel.setVisibility(View.GONE);pause.requestFocus();}else if(event.getRepeatCount()==0)exitBackPending=true;return true;}if(controls.getVisibility()==View.GONE&&(code==23||code>=19&&code<=22)){controls.setVisibility(View.VISIBLE);pause.requestFocus();return true;}return super.onKeyDown(code,event);}
 @Override public boolean onKeyUp(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_BACK){boolean leave=exitBackPending&&!event.isCanceled();exitBackPending=false;if(leave)finish();return true;}return super.onKeyUp(code,event);}
 protected void onPause(){super.onPause();if(video!=null)video.pause();}
 protected void onResume(){super.onResume();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 protected void onDestroy(){if(video!=null){try{video.stopPlayback();}catch(Exception e){}video=null;}try{getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}catch(Exception e){}super.onDestroy();}
}


